extern UINT dc_frame_index;
extern void dc_report(const char*);
typedef struct DCContext{DCDevice*d;HWND window;HMODULE module;UINT mode,api,sdk;BOOL core;}DCContext;
static HRESULT dc_make_depth(DCContext*,UINT,DCSurface**);
static HRESULT dc_make_target(DCContext*,DCSurface**);
static HRESULT dc_reset(DCContext*);
static void dc_check(BOOL ok,const char*s){if(!ok){dc_report(s);ExitProcess(1);}}
static void dc_expect(HRESULT hr,const char*s){if(FAILED(hr)){char line[150];wsprintfA(line,"%s hr=%08lX",s,(DWORD)hr);dc_report(line);ExitProcess(1);}}
static void dc_rs(DCContext*c,D3DRENDERSTATETYPE s,DWORD v){dc_expect(DC_RS(c->d,s,v),"FAIL render state");}
static void dc_draw(DCContext*c,float z,DWORD color,UINT width){struct V{float x,y,z,w;DWORD color;}q[4]={{-.5f,-.5f,z,1,color},{width-.5f,-.5f,z,1,color},{-.5f,7.5f,z,1,color},{width-.5f,7.5f,z,1,color}},v[6];const UINT order[]={0,1,2,2,1,3};for(UINT n=0;n<6;n++)v[n]=q[order[n]];dc_expect(DC_BEGIN(c->d),"FAIL begin");dc_expect(DC_DRAW(c->d,D3DPT_TRIANGLELIST,2,v,20),"FAIL draw");dc_expect(DC_END(c->d),"FAIL end");}
static void dc_frame(DCContext*c,DCSurface*target,UINT step){dc_expect(DC_READ(c->d,target),"FAIL color readback");char line[160];wsprintfA(line,"DEPTH8 FRAME index=%u mode=%u api=%u sdk=%u step=%u readback=1",dc_frame_index++,c->mode,c->api,c->sdk,step);dc_report(line);}
static void dc_cases(DCContext*c)
{
 DCSurface*target=NULL,*depth=NULL,*msaa=NULL,*same=NULL,*back=NULL;dc_expect(dc_make_target(c,&target),"FAIL target create");dc_expect(dc_make_depth(c,0,&depth),"FAIL depth create");dc_expect(dc_make_depth(c,4,&msaa),"FAIL MSAA depth create");D3DSURFACE_DESC desc;
 for(UINT n=0;n<2;n++){DCSurface*s=n?msaa:depth;dc_expect(DC_DESC(s,&desc),"FAIL depth desc");dc_check(desc.Width==8&&desc.Height==8&&desc.Format==D3DFMT_D24S8&&desc.MultiSampleType==(D3DMULTISAMPLE_TYPE)(n?4:0)&&desc.Pool==D3DPOOL_DEFAULT&&desc.Usage==D3DUSAGE_DEPTHSTENCIL,"FAIL depth metadata");D3DLOCKED_RECT out={123,(void*)99};dc_check(DC_LOCK(s,&out,NULL,D3DLOCK_READONLY)==D3DERR_INVALIDCALL&&out.Pitch==123&&out.pBits==(void*)99,"FAIL depth lock output");DCDevice*parent=NULL;dc_expect(DC_PARENT(s,&parent),"FAIL depth parent");dc_check(parent==c->d,"FAIL depth device identity");DC_RELEASE_DEVICE(parent);}
 dc_check(!DC_RELEASE_SURFACE(msaa),"FAIL metadata sample refs");dc_expect(DC_BIND(c->d,target,depth),"FAIL target depth bind");dc_expect(DC_GET_DEPTH(c->d,&same),"FAIL depth query");dc_check(same==depth&&DC_RELEASE_SURFACE(same)==1,"FAIL cached depth identity");
 dc_expect(DC_FVF(c->d,68),"FAIL FVF");dc_rs(c,D3DRS_LIGHTING,FALSE);dc_rs(c,D3DRS_CULLMODE,D3DCULL_NONE);dc_rs(c,D3DRS_ZENABLE,TRUE);dc_rs(c,D3DRS_ZWRITEENABLE,TRUE);dc_rs(c,D3DRS_ZFUNC,D3DCMP_LESS);dc_rs(c,D3DRS_ALPHABLENDENABLE,FALSE);dc_expect(DC_TSS(c->d,0,D3DTSS_COLOROP,D3DTOP_SELECTARG2),"FAIL color op");dc_expect(DC_TSS(c->d,0,D3DTSS_COLORARG2,D3DTA_DIFFUSE),"FAIL color arg");dc_expect(DC_TSS(c->d,0,D3DTSS_ALPHAOP,D3DTOP_SELECTARG2),"FAIL alpha op");dc_expect(DC_TSS(c->d,0,D3DTSS_ALPHAARG2,D3DTA_DIFFUSE),"FAIL alpha arg");
 dc_expect(DC_CLEAR(c->d,0,NULL,D3DCLEAR_TARGET|D3DCLEAR_ZBUFFER|D3DCLEAR_STENCIL,0xff000000,1,0),"FAIL initial clear");dc_draw(c,.25f,0xffff0000,8);dc_draw(c,.75f,0xff0000ff,8);dc_frame(c,target,0);
 dc_expect(DC_DEPTH(c->d,NULL),"FAIL depth unbind");dc_expect(DC_DEPTH(c->d,depth),"FAIL depth rebind");dc_draw(c,.75f,0xff0000ff,8);dc_frame(c,target,1);
 dc_expect(DC_CLEAR(c->d,0,NULL,D3DCLEAR_ZBUFFER,0,1,0),"FAIL depth-only clear");dc_draw(c,.75f,0xff0000ff,8);dc_frame(c,target,2);
 dc_expect(DC_CLEAR(c->d,0,NULL,D3DCLEAR_TARGET|D3DCLEAR_ZBUFFER|D3DCLEAR_STENCIL,0xff000000,1,0),"FAIL stencil clear");dc_rs(c,D3DRS_STENCILENABLE,TRUE);dc_rs(c,D3DRS_STENCILMASK,255);dc_rs(c,D3DRS_STENCILWRITEMASK,255);dc_rs(c,D3DRS_STENCILFUNC,D3DCMP_ALWAYS);dc_rs(c,D3DRS_STENCILREF,7);dc_rs(c,D3DRS_STENCILPASS,D3DSTENCILOP_REPLACE);dc_rs(c,D3DRS_COLORWRITEENABLE,0);dc_draw(c,.25f,0xffff0000,4);dc_rs(c,D3DRS_ZENABLE,FALSE);dc_rs(c,D3DRS_COLORWRITEENABLE,15);dc_rs(c,D3DRS_STENCILFUNC,D3DCMP_EQUAL);dc_rs(c,D3DRS_STENCILPASS,D3DSTENCILOP_KEEP);dc_draw(c,.5f,0xff00ff00,8);dc_rs(c,D3DRS_STENCILREF,8);dc_draw(c,.5f,0xff0000ff,8);dc_frame(c,target,3);
 dc_check(!DC_RELEASE_SURFACE(depth),"FAIL depth public zero");dc_expect(DC_GET_DEPTH(c->d,&same),"FAIL revive depth");dc_check(same==depth,"FAIL revived depth identity");dc_expect(DC_DEPTH(c->d,NULL),"FAIL final depth unbind");dc_check(!DC_RELEASE_SURFACE(same),"FAIL final depth refs");dc_expect(DC_BACK(c->d,&back),"FAIL original back");dc_expect(DC_BIND(c->d,back,NULL),"FAIL restore back");dc_check(!DC_RELEASE_SURFACE(back)&&!DC_RELEASE_SURFACE(target),"FAIL final target refs");dc_expect(dc_reset(c),"FAIL resource-free Reset");dc_check(!DC_RELEASE_DEVICE(c->d),"FAIL final device refs");char line[240];wsprintfA(line,"DEPTH8 CHECK mode=%u invalidCases=%u metadata=1 depthLockRefused=1 retainedDepth=1 stencilMask=1 identity=1 reset=1 finalRefs=0",c->mode,c->core?11:0);dc_report(line);
}
